    "Frequência dos envios": "Upload frequency",
    "Intervalo mínimo de 1 dia entre envios automáticos. Envia se houver alterações e internet. O Android pode adiar o horário para economizar bateria. O Drive mantém os 4 backups mais recentes; as cópias mais antigas são removidas após um envio concluído.": "Automatic uploads are at least 1 day apart and require changes and internet. Android may delay them to save battery. Drive keeps the 4 most recent backups; older copies are removed after a successful upload.",
    "Restaurar do Drive automaticamente": "Restore from Drive automatically",
    "Consulta ao abrir ou voltar ao app, com pelo menos 15 minutos entre tentativas. Sem novas consultas enquanto você continua usando ou deixa em segundo plano. Recupera novos conteúdos automaticamente, inclusive com este painel aberto. Diferenças pedem sua escolha fora do editor e da apresentação.": "Checks when opening or returning to the app, at least 15 minutes apart. No repeat checks while you keep using it or leave it in the background. New content is recovered automatically, even with this panel open. Differences ask for your choice outside the editor and presentation.",
