    "Cole o código ou a mensagem inteira do WhatsApp, com as instruções e os links. O SePrepare reconhece apenas o código. Você poderá conferir antes de salvar.": "Paste the code or the entire WhatsApp message, including instructions and links. SePrepare recognizes just the code. You can preview before saving.",
