    "Código de compartilhamento": "Sharing code",
    "Leva só as versões marcadas, com texto, formatação, participantes, categoria e ajustes de leitura. Inclui agendamento e fixação. Conta Google, ensaios e histórico pessoal ficam no seu aparelho.": "Includes only selected versions with text, formatting, participants, category and reading settings, plus schedule and pins. Google accounts, rehearsals and personal history stay on your device.",
