    "Atualizar": "Update",
    "Preparação compartilhada pelo SePrepare.\n\nAbra o arquivo .seprepare no SePrepare e confira antes de salvar. Você também pode usar o ícone de importar → Usar arquivo.\n\nBaixar ou acessar o SePrepare:": "Preparation shared with SePrepare.\n\nOpen the .seprepare file in SePrepare and preview before saving. You can also use the import icon → Use file.\n\nDownload or open SePrepare:",
    "Preparação compartilhada pelo SePrepare": "Preparation shared with SePrepare",
    "Copie esta mensagem inteira. No SePrepare, toque no ícone de importar → Usar código → Colar código copiado → Conferir preparação. Depois, escolha Salvar no aparelho.": "Copy this entire message. In SePrepare, tap the import icon → Use code → Paste copied code → Preview preparation. Then choose Save on device.",
