    "Escolher o idioma": "Choose a language",
    "Português, inglês, espanhol e japonês": "Portuguese, English, Spanish and Japanese",
    "Nos Ajustes, abra Idioma do aplicativo e escolha Português (Brasil), English, Español ou 日本語. A interface muda na hora e a escolha fica salva no aparelho.": "In Settings, open App language and choose Português (Brasil), English, Español or 日本語. The interface changes immediately and the choice is saved on your device.",
    "O idioma altera menus, mensagens e o guia. Seus discursos, falas e anotações permanecem como você escreveu. A ferramenta de revisão continua sendo de português.": "Language changes menus, messages and the guide. Your speeches, lines and notes stay as written. The review tool continues to check Portuguese.",
    ". Se a análise após corrigir estiver marcada, a prévia de formatação abre em seguida.": ". If analysis after correction is enabled, a formatting preview opens next.",
    ". O app lê o texto completo, compara as ideias de cada seção e sugere palavras-chave em negrito e pontos importantes com marca-texto. Confira os trechos e seu contexto na prévia e aplique o que preferir.": ". The app reads all text and compares each section's ideas, suggesting bold keywords and highlights for key points. Review passages in context and apply your choices.",
    "no editor e toque em": "in the editor and tap",
    ", na linha de": "in the row with",
    ". Em": ". In",
    ". Durante a contagem, tocar no tempo ou no botão principal pausa; toque novamente para continuar.": ". While running, tap the time or the main button to pause; tap again to resume.",
    "fones de ouvido": "headphones",
    ". Escolha uma voz offline para ouvir sem internet.": ". Choose an offline voice to listen without internet.",
    "a mensagem inteira do WhatsApp": "the entire WhatsApp message",
    ". O aplicativo reconhece apenas o código.": ". The app recognizes only the code.",
    ". O texto simples acompanha somente o link do SePrepare. Se o navegador baixar o arquivo em vez de compartilhar, copie a mensagem exibida e envie junto.": ". Plain text includes only the SePrepare link. If the browser downloads rather than shares a file, copy the shown message and send it with the file.",
    "apagar (⌫)": "delete (⌫)",
    "no teclado.": "on the keyboard.",
    ". Nos": ". In",
    "e escolha": "and choose",
    ". Não há envio por hora. Antes de um envio manual sobre um backup existente, confira e confirme. O Drive mantém": ". There are no hourly uploads. Before manually uploading over an existing backup, review and confirm. Drive keeps",
    "os 4 backups mais recentes": "the 4 most recent backups",
    ". Só depois de confirmar o envio, o app remove os excedentes, começando pelo mais antigo.": ". Only after confirming the upload does the app remove extra copies, starting with the oldest.",
    ". Datas ajudam a comparar. Textos alternativos ficam como versões no mesmo item, com formatação, anotações e ensaios.": ". Dates help compare. Alternative texts become versions of the same item, with formatting, notes and rehearsals.",
    ". Você pode restaurá-lo por até 30 dias; esvaziar a lixeira apaga os itens de forma definitiva.": ". You can restore it for up to 30 days; emptying the trash deletes items permanently.",
