    "As atualizações do SePrepare são verificadas e aplicadas automaticamente quando o aplicativo está livre, sem precisar baixar novamente os recursos offline que não mudaram.": "SePrepare checks for and applies updates automatically when the app is idle. Unchanged offline resources do not need to be downloaded again.",
