    "Os dados foram salvos; a cópia de recuperação local foi mantida.": "Data was saved; the local recovery copy was kept.",
    "Os envios automáticos respeitam a frequência escolhida: diariamente, semanalmente ou a cada 30 dias. Editar salva no aparelho, sem antecipar o próximo backup. Quando chegar a data, o Drive envia somente se houver alterações. Falhas podem ser tentadas novamente após 5 minutos, com o aplicativo aberto, internet e autorização válida. São mantidos os 4 backups mais recentes.": "Automatic backups follow your chosen schedule: daily, weekly, or every 30 days. Editing saves locally without bringing the next backup forward. When due, Drive uploads only if there are changes. Failed uploads can retry after 5 minutes while the app is open, online, and authorized. The 4 newest backups are kept.",
