    ". Não há envio por hora. Antes de um envio manual sobre um backup existente, confira e confirme; a cópia anterior continua guardada.": ". There are no hourly uploads. Before manually uploading over an existing backup, review and confirm; the previous copy is kept.",
    "Seus discursos, partes, versões, anotações e ensaios continuam salvos automaticamente no banco local (IndexedDB) e, quando disponível, em arquivos internos (OPFS), mesmo sem proteção persistente confirmada. A confirmação acima vem da resposta do iPhone a": "Your speeches, parts, versions, notes, and rehearsals are still saved automatically in the local database (IndexedDB) and, when available, internal files (OPFS), even without confirmed persistent protection. The status above comes from the iPhone's response to",
    "Os discursos são salvos automaticamente na memória local do aparelho. As cópias de recuperação também são criadas automaticamente. Para guardar um backup independente em Arquivos ou compartilhar, use": "Speeches are saved automatically in local device storage. Recovery copies are also created automatically. To keep an independent backup in Files or share it, use",
