    "Não foi possível salvar sua confirmação. Tente novamente.": "Your confirmation could not be saved. Please try again.",
    "A leitura acompanha o idioma do aplicativo por padrão. Em Ajustes de áudio, você pode escolher outro idioma, uma voz e a velocidade. Vozes offline funcionam sem internet.": "Reading follows the app language by default. In Audio settings, you can choose another language, a voice and the speed. Offline voices work without internet.",
    "Idioma da leitura": "Reading language",
    "Acompanhar idioma do aplicativo": "Follow app language",
