    "indisponível": "unavailable",
    "A seleção automática prioriza uma voz offline do idioma escolhido. A disponibilidade depende das vozes instaladas no Android.": "Automatic selection prefers an offline voice in the chosen language. Availability depends on the voices installed on Android.",
    "Nenhuma voz disponível neste idioma. Toque em Instalar ou gerenciar vozes para adicionar uma voz.": "No voice is available in this language. Tap Install or manage voices to add one.",
    "O motor de voz não está disponível. Abra os ajustes de texto em voz do Android.": "The speech engine is unavailable. Open the Android text-to-speech settings.",
    "Não há voz disponível para o idioma da leitura. Abra Ajustes de áudio para instalar ou escolher uma voz.": "No voice is available for the reading language. Open Audio settings to install or choose a voice.",
    "A leitura acompanha o idioma do aplicativo por padrão. No botão de <strong>fones de ouvido</strong> ou em <strong>Ajustes de áudio</strong>, escolha outro idioma, uma voz ou a velocidade. Para voltar ao automático, selecione <strong>Acompanhar idioma do aplicativo</strong>.": "Reading follows the app language by default. Use the <strong>headphones</strong> button or <strong>Audio settings</strong> to choose another language, a voice or the speed. To return to automatic mode, select <strong>Follow app language</strong>.",
    "Parar áudio": "Stop audio",
    "Parar áudio · arraste para mover": "Stop audio · drag to move",
    "Posição da leitura": "Reading position",
    "Avançar ou recuar a leitura": "Seek forward or backward",
    "Arraste para voltar ou avançar no texto.": "Drag to move backward or forward in the text.",
    "{0}% do texto": "{0}% of the text",
    "Texto para testar a voz": "Voice preview text",
    "Use a frase de exemplo ou escreva um texto. O teste não altera seus discursos.": "Use the sample sentence or write your own text. The preview does not change your speeches.",
    "Testar voz": "Preview voice",
    "Parar teste": "Stop preview",
    "Teste de voz": "Voice preview",
    "Abaixo dos botões, arraste a <strong>barra de leitura</strong> para voltar ou avançar no texto. O número indica a porcentagem do texto; o cronômetro continua independente.": "Below the buttons, drag the <strong>reading slider</strong> to move backward or forward in the text. The number shows the percentage of the text; the stopwatch remains independent.",
    "Nos Ajustes de áudio, use a frase de exemplo ou escreva em <strong>Texto para testar a voz</strong> e toque em <strong>Testar voz</strong>. O teste usa o idioma, a voz e a velocidade escolhidos sem alterar suas preparações.": "In Audio settings, use the sample sentence or write in <strong>Voice preview text</strong>, then tap <strong>Preview voice</strong>. The preview uses the selected language, voice and speed without changing your preparations.",
    "Ao sair da apresentação ou rolar os controles para fora da tela, aparece um botão flutuante para parar o áudio. Arraste para posicioná-lo onde preferir; toque para parar. O teste de voz e a leitura não alteram o cronômetro.": "When you leave the presentation or scroll past its controls, a floating audio stop button appears. Drag it to your preferred position; tap it to stop. Voice previews and reading do not affect the stopwatch.",
    "Português (Brasil)": "Portuguese (Brazil)",
