    "Voz salva indisponível": "Saved voice unavailable",
    "Offline": "Offline",
    "Online": "Online",
    "Atualizar vozes": "Refresh voices",
    "Todas as vozes disponíveis continuam na lista. Escolher uma voz fixa o idioma dela até você voltar ao automático.": "All available voices stay in the list. Choosing a voice keeps its language until you return to automatic mode.",
    "As vozes ainda estão carregando. Aguarde ou toque em Atualizar vozes.": "Voices are still loading. Wait or tap Refresh voices.",
    "Não foi possível consultar o motor de voz. Atualize a lista ou abra Instalar ou gerenciar vozes.": "The speech engine could not be reached. Refresh the list or open Install or manage voices.",
    "Voz pronta em {0}. Você pode escolher outra voz da lista.": "Voice ready in {0}. You can choose another voice from the list.",
    "A voz salva não está disponível neste aparelho. Escolha outra voz ou abra Instalar ou gerenciar vozes.": "The saved voice is unavailable on this device. Choose another voice or open Install or manage voices.",
    "A voz para {0} precisa ser instalada. Abra Instalar ou gerenciar vozes. As outras vozes continuam disponíveis para escolha manual.": "The voice for {0} needs to be installed. Open Install or manage voices. Other voices remain available for manual selection.",
    "O motor de voz atual não oferece {0}. Abra Instalar ou gerenciar vozes para verificar outro motor ou escolha uma das vozes disponíveis.": "The current speech engine does not offer {0}. Open Install or manage voices to check another engine, or choose an available voice.",
    "Nenhuma voz para {0} foi encontrada. Abra Instalar ou gerenciar vozes ou escolha outra voz da lista.": "No voice for {0} was found. Open Install or manage voices, or choose another voice from the list.",
    "A lista mantém as vozes dos quatro idiomas, mesmo ao mudar a interface. Escolha qualquer voz para fixar seu idioma e região. Variantes diferentes e opções <strong>Offline</strong> e <strong>Online</strong> ficam identificadas; repetições da mesma voz são agrupadas.": "Voices in all four languages stay in the list when you change the interface language. Choose any voice to keep its language and region. Different variants and <strong>Offline</strong> and <strong>Online</strong> options are labeled; repeated entries for the same voice are grouped.",
    "Se faltar japonês ou outro idioma, confira o aviso e abra <strong>Instalar ou gerenciar vozes</strong>. Depois de instalar, volte ao aplicativo: a lista se atualiza sem perder suas escolhas. Se necessário, toque em <strong>Atualizar vozes</strong>. Escolha uma voz offline para ouvir sem internet.": "If Japanese or another language is missing, check the message and open <strong>Install or manage voices</strong>. After installing, return to the app: the list refreshes without losing your choices. If needed, tap <strong>Refresh voices</strong>. Choose an offline voice to listen without internet.",
    "Ao mudar o idioma do aplicativo, a leitura seleciona automaticamente a Voz 1 correspondente. Em Ajustes de áudio, você pode escolher outra voz offline, a voz padrão do aparelho e a velocidade.": "When you change the app language, read-aloud automatically selects the corresponding Voice 1. In Audio settings, you can choose another offline voice, the device default voice, and the speed.",
    "Ao mudar o idioma do aplicativo, a leitura passa automaticamente para a Voz 1 correspondente. Aqui você também pode escolher outra voz offline ou a voz padrão do aparelho.": "When you change the app language, read-aloud automatically switches to the corresponding Voice 1. Here you can also choose another offline voice or the device default voice.",
    "Nenhuma voz offline instalada nos idiomas do aplicativo. Instale uma voz nas configurações do Android ou use a voz padrão do aparelho.": "No offline voice is installed for the app languages. Install a voice in Android settings or use the device default voice.",
    "Não há voz offline instalada em {0}. Abra Instalar ou gerenciar vozes para baixar o pacote de voz no Android.": "No offline voice is installed for {0}. Open Install or manage voices to download the voice package on Android.",
    "Ao mudar o idioma do aplicativo nos Ajustes, a leitura passa automaticamente para a <strong>Voz 1</strong> do idioma escolhido. No botão de <strong>fones de ouvido</strong> ou em <strong>Ajustes de áudio</strong>, você pode trocar a <strong>Voz de leitura</strong> e ajustar a velocidade.": "When you change the app language in Settings, read-aloud automatically switches to <strong>Voice 1</strong> of the chosen language. Using the <strong>headphones</strong> button or in <strong>Audio settings</strong>, you can change the <strong>Reading voice</strong> and adjust the speed.",
    "A lista exibe apenas vozes offline, agrupadas por idioma, além de uma única opção <strong>Voz padrão do aparelho</strong> que vale para todos os idiomas.": "The list shows only offline voices grouped by language, plus a single <strong>Device default voice</strong> option that works for all languages.",
    "Nos Ajustes de áudio, use a frase de exemplo ou escreva em <strong>Texto para testar a voz</strong> e toque em <strong>Testar voz</strong>. O teste usa a voz e a velocidade escolhidas sem alterar suas preparações.": "In Audio settings, use the sample sentence or type in <strong>Text to test the voice</strong> and tap <strong>Test voice</strong>. The test uses the chosen voice and speed without changing your preparations.",
    "Se faltar japonês ou outro idioma, confira o aviso e abra <strong>Instalar ou gerenciar vozes</strong>. Depois de instalar, volte ao aplicativo: a lista se atualiza sem perder suas escolhas. Se necessário, toque em <strong>Atualizar vozes</strong>.": "If Japanese or another language is missing, check the notice and open <strong>Install or manage voices</strong>. After installing, return to the app: the list updates without losing your choices. If needed, tap <strong>Refresh voices</strong>.",
    "Backup e recuperação": "Backup and recovery",
    "Há diferenças para conferir": "There are differences to review",
    "Confira as versões antes do próximo envio.": "Review the versions before the next upload.",
    "Backup automático desligado": "Automatic backup is off",
    "As próximas alterações aguardam um envio manual.": "Future changes will wait for a manual backup.",
