    "O SePrepare foi desenvolvido para facilitar a criação, organização e preparação de discursos, demonstrações e apresentações. Reúne ferramentas de escrita, revisão, treinamento e gerenciamento de conteúdos em um único lugar.": "SePrepare was developed to simplify creating, organizing and preparing speeches, demonstrations and presentations. It brings writing, review, rehearsal and content management tools together in one place.",
