    "O backup envia quando há uma <strong>alteração real</strong>. Salvar novamente sem mudar o conteúdo não cria outra cópia. Alterações próximas são reunidas. Após confirmar um backup, o próximo envio aguarda pelo menos <strong>10 segundos</strong>. As etapas do mesmo backup não têm essa pausa. Sem internet, o envio aguarda e tenta novamente. O Android pode adiar a execução em segundo plano.": "Real changes are combined into a backup. After a backup is confirmed, the next upload waits at least 10 seconds. Requests within the same backup do not have this fixed delay. Saving unchanged content does not create another copy. Offline uploads wait and retry. Keep the app open; the operating system may delay background activity.",
    "Salvar uma cópia deste aparelho?": "Save a copy of this device?",
