    "Frequência dos envios": "Frecuencia de envío",
    "Intervalo mínimo de 1 dia entre envios automáticos. Envia se houver alterações e internet. O Android pode adiar o horário para economizar bateria. O Drive mantém os 4 backups mais recentes; as cópias mais antigas são removidas após um envio concluído.": "Los envíos automáticos tienen un intervalo mínimo de 1 día y requieren cambios e internet. Android puede aplazarlos para ahorrar batería. Drive conserva las 4 copias más recientes; las antiguas se eliminan después de un envío correcto.",
    "Restaurar do Drive automaticamente": "Restaurar de Drive automáticamente",
    "Consulta ao abrir ou voltar ao app, com pelo menos 15 minutos entre tentativas. Sem novas consultas enquanto você continua usando ou deixa em segundo plano. Recupera novos conteúdos automaticamente, inclusive com este painel aberto. Diferenças pedem sua escolha fora do editor e da apresentação.": "Consulta al abrir o volver a la aplicación, con al menos 15 minutos entre intentos. No repite consultas durante el uso continuo ni en segundo plano. Recupera contenido nuevo automáticamente, incluso con este panel abierto. Si hay diferencias, pide tu elección fuera del editor y la presentación.",
