    "Um caderno vazio não será enviado automaticamente. Você pode recuperar o backup existente ou ativar a frequência para suas próximas preparações.": "Un cuaderno vacío no se envía automáticamente. Recupera la copia existente o activa una frecuencia para tus próximas preparaciones.",
    "Este aparelho está vazio. Escolha Preservar os dois para recuperar os dados do Drive antes do envio.": "Este dispositivo está vacío. Elige Conservar ambos para recuperar los datos de Drive antes de enviar.",
