    ": com formatação, sem formatação ou interpretando Markdown.": ": con formato, sin formato o interpretando Markdown.",
    "Selecione um trecho": "Selecciona un fragmento",
    "antes de usar negrito, cores, fontes e outras ferramentas. Sem seleção, a ferramenta pode atuar no texto inteiro.": "antes de usar negrita, colores, fuentes u otras herramientas. Sin selección, la herramienta puede afectar a todo el texto.",
    "Em": "En",
    ", você encontra listas, checklist, citação, alinhamento, maiúsculas e minúsculas.": ", encontrarás listas, tareas, citas, alineación y cambios de mayúsculas y minúsculas.",
    "As alterações ficam como rascunho no aparelho. Toque em Salvar para atualizar a apresentação; o botão vira Visualizar. Ao sair sem salvar, o rascunho continua no editor e a apresentação mantém o texto confirmado.": "Los cambios se guardan como borrador en el dispositivo. Toca Guardar para actualizar la presentación; el botón pasa a Visualizar. Al salir sin guardar, el borrador sigue en el editor y la presentación conserva el texto confirmado.",
    "Montar uma parte com participantes": "Crear una parte con participantes",
    "Escreva primeiro. Identifique as falas depois.": "Escribe primero. Asigna las intervenciones después.",
    "Toque em": "Toca",
    "+ → Parte": "+ → Parte",
    "e escreva ou cole todo o diálogo.": "y escribe o pega todo el diálogo.",
    "Abra": "Abre",
    "Participantes": "Participantes",
    "e adicione os nomes. Selecione cada fala no texto e toque no nome de quem fala.": "y añade los nombres. Selecciona cada intervención y toca el nombre de quien habla.",
    "Na apresentação, use": "En la presentación, usa",
    "para escolher seu participante. O filtro ao lado mostra somente suas falas; toque novamente para ver todas.": "para elegir tu participante. El filtro de al lado muestra solo tus intervenciones; toca de nuevo para verlas todas.",
    "Você pode atribuir vários trechos à mesma pessoa e usar mais de dois participantes.": "Puedes asignar varios fragmentos a una misma persona y usar más de dos participantes.",
    "Revisar e destacar as ideias": "Revisar y resaltar ideas",
    "Português, citações, negrito e marca-texto": "Portugués, citas, negrita y resaltado",
    ", confira as sugestões e marque apenas as que deseja aplicar. A opção de preservar citações já vem ativada.": ", revisa las sugerencias y marca solo las que quieras aplicar. La conservación de citas está activada de forma predeterminada.",
    "Use": "Usa",
    "Para analisar sem revisar primeiro, toque em": "Para analizar sin revisar primero, toca",
    "Selecione um trecho para revisar ou analisar só aquela parte. O mesmo texto, título e participantes geram as mesmas sugestões, inclusive após aplicar a formatação. A revisão local e a análise funcionam sem internet; a revisão online é opcional nos Ajustes. Toque em Salvar para confirmar as alterações na apresentação.": "Selecciona un fragmento para revisar o analizar solo esa parte. El mismo texto, título y participantes generan las mismas sugerencias, incluso después de aplicar formato. La revisión local y el análisis funcionan sin internet; la revisión online es opcional en Ajustes. Toca Guardar para confirmar los cambios en la presentación.",
    "Anotar orientações privadas": "Anotar indicaciones privadas",
    "Lembretes vinculados aos trechos, só para você": "Recordatorios vinculados a fragmentos, solo para ti",
    ", ao lado de Revisar português e Analisar e formatar. Escreva uma orientação ou escolha uma sugestão rápida.": ", junto a Revisar portugués y Analizar y dar formato. Escribe una indicación o elige una sugerencia rápida.",
    "No editor, toque no ícone de nota na margem para consultar, editar ou excluir. Cada versão guarda suas próprias orientações.": "En el editor, toca el icono de nota del margen para consultar, editar o eliminar. Cada versión conserva sus propias notas.",
    "Na apresentação, a orientação já aparece escrita": "En la presentación, la indicación aparece escrita",
    "acima do trecho, à direita, em letra menor e grifada": "encima del fragmento, a la derecha, con letra pequeña y resaltada",
    ", identificada como Anotação, sem precisar abrir nada. Toque no": ", identificada como Nota, sin abrir nada. Toca el",
    "ícone de anotação": "icono de nota",
    ", para mostrar ou ocultar todas; o botão muda de cor quando está ligado.": "para mostrar u ocultar todas las notas; cambia de color al activarse.",
    "As anotações não entram na contagem de palavras, no áudio nem no compartilhamento por texto, arquivo ou HTML. No código, só entram se você marcar Incluir minhas anotações privadas. Seus backups pessoais também guardam as anotações.": "Las notas no cuentan como palabras ni se incluyen en el audio o al compartir texto, archivo o HTML. En el código solo se incluyen si marcas Incluir mis notas privadas. Las copias personales también las guardan.",
    "Experimentar outras versões": "Probar otras versiones",
    "Vários textos dentro da mesma preparação": "Varios textos en una misma preparación",
    "Toque no": "Toca el",
    "nome da versão": "nombre de la versión",
    "no editor. Escolha uma existente, crie uma em branco ou duplique a atual.": "en el editor. Elige una existente, crea una en blanco o duplica la actual.",
    "A cópia abre para edição com a mesma formatação. Cada versão tem texto e ensaios próprios; os ensaios não são copiados.": "La copia se abre para editar con el mismo formato. Cada versión tiene texto y ensayos propios; los ensayos no se copian.",
    "Na apresentação, o mesmo seletor troca a versão exibida. Se houver um ensaio contando, pause ou encerre antes de trocar.": "En la presentación, el mismo selector cambia la versión mostrada. Pausa o finaliza un ensayo en marcha antes de cambiar.",
    "A troca guarda os rascunhos sem publicá-los. Toque em Salvar no editor para confirmar as alterações da preparação. Nas opções da versão você pode renomear, comparar, consultar ensaios e restaurar textos anteriores.": "El cambio conserva los borradores sin publicarlos. Toca Guardar en el editor para confirmar los cambios. Las opciones de versión permiten renombrar, comparar, consultar ensayos y restaurar textos anteriores.",
    "Apresentar e medir seu tempo": "Presentar y medir tu tiempo",
    "Pausar, continuar, encerrar e zerar": "Pausar, continuar, terminar y reiniciar",
    "Salve e toque em": "Guarda y toca",
    ", ajuste tamanho, fonte, zoom e espaçamento.": ", ajusta tamaño, fuente, zoom y espaciado.",
    "Stop": "Detener",
    "para encerrar e registrar o ensaio. No controle inferior do celular, Stop aparece depois de pausar.": "para terminar y guardar el ensayo. En el control inferior del móvil, Detener aparece al pausar.",
    "Zerar limpa a contagem sem registrar um ensaio. Os tempos salvos ficam na versão usada. O modo foco deixa a leitura em destaque.": "Reiniciar borra la cuenta sin guardar el ensayo. Los tiempos se guardan en la versión usada. El modo de enfoque destaca la lectura.",
    "Ouvir o texto em voz alta": "Escuchar el texto en voz alta",
