    "Atualizar": "Actualizar",
    "Preparação compartilhada pelo SePrepare.\n\nAbra o arquivo .seprepare no SePrepare e confira antes de salvar. Você também pode usar o ícone de importar → Usar arquivo.\n\nBaixar ou acessar o SePrepare:": "Preparación compartida con SePrepare.\n\nAbre el archivo .seprepare en SePrepare y revisa antes de guardar. También puedes usar el icono de importar → Usar archivo.\n\nDescargar o abrir SePrepare:",
    "Preparação compartilhada pelo SePrepare": "Preparación compartida con SePrepare",
    "Copie esta mensagem inteira. No SePrepare, toque no ícone de importar → Usar código → Colar código copiado → Conferir preparação. Depois, escolha Salvar no aparelho.": "Copia todo este mensaje. En SePrepare, toca el icono de importar → Usar código → Pegar código copiado → Revisar preparación. Después elige Guardar en el dispositivo.",
