    "Escolher o idioma": "Elegir el idioma",
    "Português, inglês, espanhol e japonês": "Portugués, inglés, español y japonés",
    "Nos Ajustes, abra Idioma do aplicativo e escolha Português (Brasil), English, Español ou 日本語. A interface muda na hora e a escolha fica salva no aparelho.": "En Ajustes, abre Idioma de la aplicación y elige Português (Brasil), English, Español o 日本語. La interfaz cambia al instante y la elección se guarda en tu dispositivo.",
    "O idioma altera menus, mensagens e o guia. Seus discursos, falas e anotações permanecem como você escreveu. A ferramenta de revisão continua sendo de português.": "El idioma cambia los menús, mensajes y la guía. Tus discursos, intervenciones y notas se mantienen como los escribiste. La herramienta de revisión sigue siendo de portugués.",
    ". Se a análise após corrigir estiver marcada, a prévia de formatação abre em seguida.": ". Si está activado el análisis tras corregir, se abre después la vista previa del formato.",
    ". O app lê o texto completo, compara as ideias de cada seção e sugere palavras-chave em negrito e pontos importantes com marca-texto. Confira os trechos e seu contexto na prévia e aplique o que preferir.": ". La aplicación lee todo el texto y compara las ideas de cada sección, sugiriendo palabras clave en negrita y puntos importantes resaltados. Revisa el contexto y aplica lo que prefieras.",
    "no editor e toque em": "en el editor y toca",
    ", na linha de": ", en la fila de",
    ". Em": ". En",
    ". Durante a contagem, tocar no tempo ou no botão principal pausa; toque novamente para continuar.": ". Mientras cuenta, toca el tiempo o el botón principal para pausar; vuelve a tocar para continuar.",
    "fones de ouvido": "auriculares",
    ". Escolha uma voz offline para ouvir sem internet.": ". Elige una voz sin conexión para escuchar sin internet.",
