    ". O aplicativo reconhece apenas o código.": ". La aplicación reconoce solo el código.",
    ". O texto simples acompanha somente o link do SePrepare. Se o navegador baixar o arquivo em vez de compartilhar, copie a mensagem exibida e envie junto.": ". El texto simple incluye solo el enlace de SePrepare. Si el navegador descarga el archivo en vez de compartirlo, copia el mensaje mostrado y envíalo junto al archivo.",
    "apagar (⌫)": "borrar (⌫)",
