    ". Nos": ". En",
    "e escolha": "y elige",
    ". Não há envio por hora. Antes de um envio manual sobre um backup existente, confira e confirme. O Drive mantém": ". No hay envíos por hora. Antes de enviar manualmente sobre una copia existente, revisa y confirma. Drive conserva",
    "os 4 backups mais recentes": "las 4 copias más recientes",
    ". Só depois de confirmar o envio, o app remove os excedentes, começando pelo mais antigo.": ". Solo después de confirmar el envío se eliminan las copias sobrantes, empezando por la más antigua.",
    ". Datas ajudam a comparar. Textos alternativos ficam como versões no mesmo item, com formatação, anotações e ensaios.": ". Las fechas ayudan a comparar. Los textos alternativos quedan como versiones del mismo elemento, con formato, notas y ensayos.",
    ". Você pode restaurá-lo por até 30 dias; esvaziar a lixeira apaga os itens de forma definitiva.": ". Puedes restaurarlo hasta 30 días después; vaciar la papelera elimina los elementos definitivamente.",
