    "Os envios automáticos respeitam a frequência escolhida: diariamente, semanalmente ou a cada 30 dias. Editar salva no aparelho, sem antecipar o próximo backup. Quando chegar a data, o Drive envia somente se houver alterações. Falhas podem ser tentadas novamente após 5 minutos, com o aplicativo aberto, internet e autorização válida. São mantidos os 4 backups mais recentes.": "Las copias automáticas siguen la frecuencia elegida: diaria, semanal o cada 30 días. Editar guarda en el dispositivo sin adelantar la próxima copia. Al llegar la fecha, Drive envía solo si hay cambios. Los fallos pueden reintentarse tras 5 minutos con la aplicación abierta, conexión y autorización válida. Se conservan las 4 copias más recientes.",
    "Outra versão do aplicativo está usando o armazenamento. Feche a outra aba e recarregue.": "Otra versión está usando el almacenamiento. Cierra la otra pestaña y recarga.",
