    ". Não há envio por hora. Antes de um envio manual sobre um backup existente, confira e confirme; a cópia anterior continua guardada.": ". No hay envíos por hora. Antes de enviar manualmente sobre una copia existente, revisa y confirma; la copia anterior se conserva.",
    "Seus discursos, partes, versões, anotações e ensaios continuam salvos automaticamente no banco local (IndexedDB) e, quando disponível, em arquivos internos (OPFS), mesmo sem proteção persistente confirmada. A confirmação acima vem da resposta do iPhone a": "Tus discursos, partes, versiones, notas y ensayos siguen guardándose automáticamente en la base local (IndexedDB) y, cuando está disponible, en archivos internos (OPFS), incluso sin protección persistente confirmada. El estado anterior proviene de la respuesta del iPhone a",
    "Os discursos são salvos automaticamente na memória local do aparelho. As cópias de recuperação também são criadas automaticamente. Para guardar um backup independente em Arquivos ou compartilhar, use": "Los discursos se guardan automáticamente en la memoria local. También se crean copias de recuperación automáticas. Para guardar una copia independiente en Archivos o compartirla, usa",
