    "Abrir o endereço diretamente em qualquer navegador não libera o editor. Para usar, inicie o aplicativo instalado pela Tela de Início.": "Abrir la dirección directamente en un navegador no habilita el editor. Para usarlo, abre la aplicación instalada desde la pantalla de inicio.",
