    "O envio desta alteração está pendente. Veja Backup e recuperação nos Ajustes.": "Este cambio está pendiente de envío. Consulta Copia de seguridad y recuperación en Ajustes.",
    "Proteção automática": "Protección automática",
    "Backup automático": "Copia automática",
    "Salva quando o conteúdo muda de verdade.": "Guarda cuando el contenido cambia realmente.",
    "Recuperação automática": "Recuperación automática",
    "Ao abrir o app, recupera novidades do Drive. Versões diferentes pedem sua escolha.": "Al abrir la aplicación, recupera novedades de Drive. Las versiones diferentes requieren tu elección.",
    "Como a proteção funciona": "Cómo funciona la protección",
    "Alterações próximas são reunidas em uma cópia, com pelo menos 10 segundos entre a confirmação de um backup e o próximo envio. As etapas do mesmo backup não têm essa pausa. Sem internet, o envio aguarda e tenta novamente. O Android pode adiar a execução em segundo plano.": "Los cambios reales se reúnen en una copia. Después de confirmar una copia, el siguiente envío espera al menos 10 segundos. Las solicitudes de la misma copia no tienen esa pausa fija. Guardar sin cambios no crea otra copia. Sin conexión, el envío espera y vuelve a intentarlo. Mantén la aplicación abierta; el sistema puede aplazar tareas en segundo plano.",
    "A recuperação consulta ao abrir ou voltar ao aplicativo, com pelo menos 15 minutos entre tentativas. Seus textos diferentes podem ser preservados como versões no mesmo item.": "La recuperación comprueba al abrir o volver a la aplicación, con al menos 15 minutos entre intentos. Los textos diferentes pueden conservarse como versiones del mismo elemento.",
    "Há versões diferentes aguardando sua escolha.": "Hay versiones diferentes esperando tu elección.",
    "Cópias no Google Drive": "Copias en Google Drive",
    "Salvar uma cópia agora": "Guardar una copia ahora",
    "Recuperar meus discursos": "Recuperar mis discursos",
    "Detalhes das operações": "Detalles de las operaciones",
    "Última tentativa de envio": "Último intento de envío",
    "Última recuperação aplicada": "Última recuperación aplicada",
    "Seu backup está salvo. A limpeza de algumas cópias anteriores será tentada novamente.": "Tu copia está guardada. Se volverá a intentar limpiar algunas copias anteriores.",
    "Conecte sua conta para salvar e recuperar seus discursos automaticamente.": "Conecta tu cuenta para guardar y recuperar tus discursos automáticamente.",
    "Opções de backup": "Opciones de copia de seguridad",
