    "Conecte seu Google Drive para guardar cópias dos seus discursos, demonstrações e versões e recuperar tudo em outro aparelho.": "Conecta Google Drive para guardar copias de tus discursos, demostraciones y versiones y recuperarlo todo en otro dispositivo.",
    "Discursos, demonstrações, versões, categorias, ensaios e anotações privadas ficam nas suas cópias de segurança.": "Tus copias incluyen discursos, demostraciones, versiones, categorías, ensayos y notas privadas.",
    "Montar uma demonstração com participantes": "Crear una demostración con participantes",
    "+ → Demonstração": "+ → Demostración",
    "Os filtros Todos, Discursos e Demonstrações funcionam junto com a busca e o filtro de categorias ou fixados.": "Todos, Discursos y Demostraciones funcionan junto con la búsqueda y el filtro de categorías o fijados.",
    "O SePrepare foi desenvolvido para facilitar a criação, organização e preparação de discursos, demonstrações e apresentações. Reúne ferramentas de escrita, revisão, treinamento e gerenciamento de conteúdos em um único lugar.": "SePrepare se desarrolló para facilitar la creación, organización y preparación de discursos, demostraciones y presentaciones. Reúne herramientas de escritura, revisión, ensayo y gestión de contenidos en un solo lugar.",
