    "O backup envia quando há uma <strong>alteração real</strong>. Salvar novamente sem mudar o conteúdo não cria outra cópia. Alterações próximas são reunidas. Após confirmar um backup, o próximo envio aguarda pelo menos <strong>10 segundos</strong>. As etapas do mesmo backup não têm essa pausa. Sem internet, o envio aguarda e tenta novamente. O Android pode adiar a execução em segundo plano.": "Los cambios reales se reúnen en una copia. Después de confirmar una copia, el siguiente envío espera al menos 10 segundos. Las solicitudes de la misma copia no tienen esa pausa fija. Guardar sin cambios no crea otra copia. Sin conexión, el envío espera y vuelve a intentarlo. Mantén la aplicación abierta; el sistema puede aplazar tareas en segundo plano.",
    "Salvar uma cópia deste aparelho?": "¿Guardar una copia de este dispositivo?",
    "O backup guardará o conteúdo atual deste aparelho no Google Drive. Esta ação não recupera nem substitui os textos deste aparelho.": "La copia guarda el contenido actual de este dispositivo en Google Drive. Esta acción no recupera ni sustituye los textos de este dispositivo.",
    "As cópias anteriores permanecem no histórico, respeitando o limite de quatro backups. Para trazer textos de outro aparelho, use Recuperar meus discursos.": "Las copias anteriores permanecen en el historial, con un máximo de cuatro. Para traer textos de otro dispositivo, usa Recuperar mis discursos.",
