    "Último backup conferido": "最後に確認したバックアップ",
    "Última restauração aplicada": "最後の復元",
    "Enviar backups automaticamente": "バックアップを自動送信",
    "Frequência dos envios": "送信の頻度",
    "Intervalo mínimo de 1 dia entre envios automáticos. Envia se houver alterações e internet. O Android pode adiar o horário para economizar bateria. O Drive mantém os 4 backups mais recentes; as cópias mais antigas são removidas após um envio concluído.": "自動送信は最短でも1日間隔で、変更とインターネット接続がある場合に実行します。省電力のためAndroidが遅らせることがあります。Driveには最新4件を残し、送信完了後に古いコピーを削除します。",
    "Restaurar do Drive automaticamente": "Driveから自動復元",
    "Consulta ao abrir ou voltar ao app, com pelo menos 15 minutos entre tentativas. Sem novas consultas enquanto você continua usando ou deixa em segundo plano. Recupera novos conteúdos automaticamente, inclusive com este painel aberto. Diferenças pedem sua escolha fora do editor e da apresentação.": "アプリを開くときや戻るときに、15分以上の間隔で確認します。使用中やバックグラウンドでは繰り返し確認しません。このパネルを開いていても新しい内容を自動復元します。競合があれば、編集・発表画面の外で選択を求めます。",
    "Reconectar Google Drive": "Google Driveに再接続",
