    "Discursos, partes, versões, categorias, ensaios e anotações privadas ficam nas suas cópias de segurança.": "スピーチ、パート、バージョン、カテゴリー、リハーサル、非公開メモをバックアップします。",
    "A conexão com o Drive está disponível no aplicativo Android.": "Driveとの接続はAndroidアプリで利用できます。",
    "{0}O conteúdo fica na área privada do SePrepare na sua conta Google.": "{0}内容はGoogleアカウント内のSePrepare専用の非公開領域に保存されます。",
    "Seu backup está salvo. A remoção de algumas cópias antigas ficou pendente e será tentada no próximo envio.": "バックアップを保存しました。一部の古いコピーは削除できなかったため、次回の送信時に再試行します。",
