    "Drive: {0}": "Drive：{0}",
    "Qual conteúdo deseja usar?": "どちらの内容を使いますか？",
    "Preservar os dois": "両方を保持",
    "Recomendado · Textos diferentes do Drive ficam em outras versões no mesmo item. Dados gerais e versão ativa do aparelho são mantidos.": "推奨 · Drive側の異なる文章を同じ項目の別バージョンとして保存します。端末側の共通情報と現在のバージョンは保持します。",
    "Manter deste aparelho": "この端末の内容を使う",
    "Não importa o conteúdo do Drive. O Drive mantém as 4 cópias mais recentes.": "Driveの内容は読み込みません。Driveには最新4件のコピーを残します。",
    "Usar os do Drive": "Driveの内容を使う",
    "Usa os textos e dados gerais do Drive. Textos diferentes do aparelho ficam em outras versões; itens exclusivos são preservados.": "Driveの文章と共通情報を使います。端末側の異なる文章は別バージョンとして残し、端末だけにある項目も保持します。",
    "Já existe um backup nesta conta": "このアカウントにはバックアップがあります",
