    "Confira antes do próximo envio": "次回の送信前に確認",
    "Há conteúdos diferentes": "内容に違いがあります",
    "Recuperar suas preparações": "準備データを復元",
    "Deseja tornar o conteúdo escolhido o backup mais recente desta conta? Após o envio, ficam as 4 cópias mais recentes.": "選んだ内容をこのアカウントの最新バックアップにしますか？送信後は最新4件が残ります。",
    "O backup ficará na sua conta Google.": "バックアップはGoogleアカウントに保存されます。",
    "O Drive tem uma cópia feita fora deste aparelho. O envio automático está aguardando sua escolha.": "Driveに別の端末で作成したコピーがあります。自動送信は選択待ちです。",
    "Confira o que será recuperado do Google Drive.": "Google Driveから復元する内容を確認してください。",
    "No aparelho": "端末",
    "No Drive": "Drive",
    "{0} preparações do Drive ainda não estão neste aparelho.": "Drive内の準備データ{0}件が、まだこの端末にありません。",
    "Um caderno vazio não será enviado automaticamente. Você pode recuperar o backup existente ou ativar a frequência para suas próximas preparações.": "空のノートは自動送信しません。既存のバックアップを復元するか、今後の準備用に送信頻度を設定してください。",
    "Este aparelho está vazio. Escolha Preservar os dois para recuperar os dados do Drive antes do envio.": "この端末は空です。送信前にDriveのデータを復元するには「両方を保持」を選んでください。",
    "Este aparelho está vazio. Uma cópia vazia só será criada se você autorizar abaixo.": "この端末は空です。下で許可した場合のみ空のコピーを作成します。",
    "{0}Formatação, anotações e ensaios acompanham cada versão. Nenhum card extra é criado para os textos alternativos.": "{0}各バージョンには書式、メモ、練習記録が保存されます。別案の文章でカードが増えることはありません。",
    "Backup do Drive: {0}": "Driveのバックアップ：{0}",
    "Se eu mantiver o aparelho vazio, autorizo criar uma cópia vazia, mantendo somente as 4 cópias mais recentes.": "端末を空のままにする場合、空のバックアップを作成し、最新4件のみを残すことを許可します。",
    "Confirmar e ativar": "確認して有効にする",
