    "Confirmar escolha": "選択を確定",
    "Aplicar escolha": "選択を適用",
    "Este backup não é válido. Seu caderno foi preservado.": "無効なバックアップです。ノートは保持されています。",
    "Confirme se deseja guardar um caderno vazio ou preserve os dados do Drive.": "空のノートを保存するか、Driveのデータを保持するか確認してください。",
    "Não foi possível salvar o caderno atual.": "現在のノートを保存できませんでした。",
    "O caderno mudou durante a leitura. Confira novamente para preservar suas alterações.": "読み取り中にノートが変更されました。変更を保持するため、再度確認してください。",
    "Não foi possível guardar sua cópia de recuperação.": "復旧用コピーを保存できませんでした。",
    "Não foi possível salvar a restauração. Seu caderno foi preservado.": "復元結果を保存できませんでした。ノートは保持されています。",
    "Não foi possível salvar antes do envio.": "送信前に保存できませんでした。",
    "O caderno mudou. Confira o backup novamente antes de enviar.": "ノートが変更されました。送信前にバックアップを再確認してください。",
    "Seu conteúdo foi salvo, mas não foi possível concluir a conferência. Tente novamente.": "内容は保存しましたが、確認を完了できませんでした。再試行してください。",
