    "Não foi possível concluir. Seu caderno foi preservado.": "完了できませんでした。ノートは保持されています。",
    "Não foi possível recuperar o backup.": "バックアップを復元できませんでした。",
    "Backup conferido. Volte aos Ajustes para confirmar o envio.": "バックアップを確認しました。設定に戻って送信を確定してください。",
    "Google Drive conectado com sucesso.": "Google Driveに接続しました。",
    "Frequência ativada. Um caderno vazio não foi enviado.": "自動送信を有効にしました。空のノートは送信していません。",
    "Sua cópia já está atualizada.": "コピーはすでに最新です。",
    "Backup salvo no seu Google Drive.": "Google Driveにバックアップを保存しました。",
