    "Abra o app novamente para conferir a próxima cópia disponível.": "次のコピーを確認するには、アプリをもう一度開いてください。",
    "Desconectar o Google Drive?": "Google Driveの接続を解除しますか？",
    "Os envios e a leitura automática serão desativados neste aparelho. Seu caderno e os backups existentes serão preservados.": "この端末での自動送信と自動確認を無効にします。ノートと既存のバックアップは保持します。",
