    "Atualizar": "更新",
    "Preparação compartilhada pelo SePrepare.\n\nAbra o arquivo .seprepare no SePrepare e confira antes de salvar. Você também pode usar o ícone de importar → Usar arquivo.\n\nBaixar ou acessar o SePrepare:": "SePrepareで共有された準備データです。\n\n.seprepareファイルをSePrepareで開き、保存前に確認してください。読み込みアイコン → ファイルを使う、からも開けます。\n\nSePrepareのダウンロード・アクセス先：",
    "Preparação compartilhada pelo SePrepare": "SePrepareで共有された準備データ",
    "Copie esta mensagem inteira. No SePrepare, toque no ícone de importar → Usar código → Colar código copiado → Conferir preparação. Depois, escolha Salvar no aparelho.": "このメッセージ全体をコピーしてください。SePrepareで、読み込みアイコン → コードを使う → コピーしたコードを貼り付け → 準備内容を確認、の順に進み、「端末に保存」を選んでください。",
    "Baixar ou acessar o SePrepare:": "SePrepareのダウンロード・アクセス先：",
