    "Escolher o idioma": "言語を選ぶ",
    "Português, inglês, espanhol e japonês": "ポルトガル語・英語・スペイン語・日本語",
    "Nos Ajustes, abra Idioma do aplicativo e escolha Português (Brasil), English, Español ou 日本語. A interface muda na hora e a escolha fica salva no aparelho.": "設定の「アプリの言語」で、Português (Brasil)、English、Español、日本語から選びます。すぐに画面の言語が変わり、端末に保存されます。",
    "O idioma altera menus, mensagens e o guia. Seus discursos, falas e anotações permanecem como você escreveu. A ferramenta de revisão continua sendo de português.": "メニュー、メッセージ、ガイドの言語を変えます。スピーチ、せりふ、メモは書いたままです。校正ツールは引き続きポルトガル語用です。",
    ". Se a análise após corrigir estiver marcada, a prévia de formatação abre em seguida.": "。修正後の分析を有効にしている場合は、続いて書式の候補が表示されます。",
    ". O app lê o texto completo, compara as ideias de cada seção e sugere palavras-chave em negrito e pontos importantes com marca-texto. Confira os trechos e seu contexto na prévia e aplique o que preferir.": "。アプリが全文と各部分の要点を分析し、キーワードの太字や重要箇所の蛍光ペンを提案します。文脈を確認して必要なものを適用してください。",
    "no editor e toque em": "してから編集画面で次をタップ：",
