    "As anotações não entram na contagem de palavras, no áudio nem no compartilhamento por texto, arquivo ou HTML. Seus backups pessoais também guardam as anotações. No código, só entram se você marcar Incluir minhas anotações privadas.": "メモは文字数・単語数の集計、音声、テキスト・ファイル・HTML での共有には含まれません。個人用バックアップには保存されます。共有コードには「非公開メモを含める」を選んだ場合だけ含まれます。",
