    ". Não há envio por hora. Antes de um envio manual sobre um backup existente, confira e confirme; a cópia anterior continua guardada.": "。1時間ごとの送信はありません。既存のバックアップに手動送信する前に確認してください。以前のコピーも保持されます。",
    "Seus discursos, partes, versões, anotações e ensaios continuam salvos automaticamente no banco local (IndexedDB) e, quando disponível, em arquivos internos (OPFS), mesmo sem proteção persistente confirmada. A confirmação acima vem da resposta do iPhone a": "永続保存の保護が未確認でも、スピーチ、対話パート、バージョン、メモ、練習記録は端末内のデータベース（IndexedDB）と、利用可能な場合は内部ファイル（OPFS）に自動保存されます。上の状態は次の呼び出しへの iPhone の応答です：",
    "Os discursos são salvos automaticamente na memória local do aparelho. As cópias de recuperação também são criadas automaticamente. Para guardar um backup independente em Arquivos ou compartilhar, use": "スピーチは端末内に自動保存され、復旧用コピーも自動で作成されます。独立したバックアップを「ファイル」に保存したり共有したりするには、次の操作を使ってください：",
    "100% sem internet": "完全オフライン",
    "já está aberto como aplicativo instalado na tela inicial. Seus discursos e partes ficam salvos diretamente na memória persistente do aparelho.": "はホーム画面のアプリとして開いています。スピーチと対話パートは端末の永続ストレージに直接保存されます。",
