    "Ritmo equilibrado, ideal para uso geral.": "幅広い場面に適した標準的なペース。",
    "Demonstração sem título": "無題の実演",
    "Discursos e demonstrações, no seu ritmo.": "自分のペースで、スピーチと実演を準備。",
    "Organize seus discursos e demonstrações do seu jeito.": "スピーチや実演を自分らしく整理。",
    "Escreva ou cole a demonstração inteira e identifique quem fala.": "実演全体を入力または貼り付けてから、話す人を指定します。",
    "Demonstrações": "実演",
    "Sua próxima demonstração": "次の実演",
    "Discursos e demonstrações": "スピーチと実演",
    "Crie um discurso ou uma demonstração com participantes e falas.": "スピーチ、または参加者とせりふのある実演を作成しましょう。",
    "Agende um discurso ou uma demonstração e escolha quando receber os lembretes.": "スピーチや実演の予定と、通知を受け取る時刻を設定します。",
    "Escolha o nome, o ícone e a cor para organizar seus discursos e demonstrações.": "名前、アイコン、色を選んでスピーチや実演を整理します。",
