    "O SePrepare foi desenvolvido para facilitar a criação, organização e preparação de discursos, demonstrações e apresentações. Reúne ferramentas de escrita, revisão, treinamento e gerenciamento de conteúdos em um único lugar.": "SePrepareはスピーチ、実演、発表の作成・整理・準備を簡単にするために開発されました。執筆、校正、練習、内容管理のツールを一つにまとめています。",
