    "Um texto em branco dentro da mesma preparação. Os participantes atuais são mantidos nas demonstrações.": "同じ準備データに空の文章を作成します。実演の現在の参加者は保持されます。",
    "Use até 50 participantes nesta demonstração.": "参加者は50人までです。",
