    "Testar a voz": "音声を試す",
    "O backup envia quando há uma <strong>alteração real</strong>. Salvar novamente sem mudar o conteúdo não cria outra cópia. Alterações próximas são reunidas. Após confirmar um backup, o próximo envio aguarda pelo menos <strong>10 segundos</strong>. As etapas do mesmo backup não têm essa pausa. Sem internet, o envio aguarda e tenta novamente. O Android pode adiar a execução em segundo plano.": "実際の変更を1つのバックアップにまとめます。バックアップの確認後、次の送信まで10秒以上空けます。同じバックアップ内のリクエストには、この固定待機時間はありません。同じ内容を保存してもコピーは増えません。オフラインでは送信を待機して再試行します。アプリを開いたままにしてください。OSによりバックグラウンド処理が遅れる場合があります。",
    "Salvar uma cópia deste aparelho?": "この端末のコピーを保存しますか？",
    "O backup guardará o conteúdo atual deste aparelho no Google Drive. Esta ação não recupera nem substitui os textos deste aparelho.": "この端末の現在の内容をGoogle Driveに保存します。この操作で端末のテキストが復元または置換されることはありません。",
    "As cópias anteriores permanecem no histórico, respeitando o limite de quatro backups. Para trazer textos de outro aparelho, use Recuperar meus discursos.": "以前のコピーは最大4件の履歴に残ります。別の端末のテキストを読み込むには、スピーチの復元を使用してください。",
    "Confirme se deseja guardar um caderno vazio.": "空のノートを保存する場合は確認してください。",
