// Speech detection 1.0.74: platform microphone guidance.
Object.assign(catalogs.en,{"Pausa na fala para avançar": "Pause in speech before advancing", "Pausa na fala": "Pause in speech", "A detecção local de fala usa o microfone apenas na sua vez. Ruídos de fundo não precisam desaparecer para avançar. Nenhum áudio é gravado ou enviado.": "Local speech detection uses the microphone only on your turn. Background noise does not need to stop before advancing. No audio is recorded or sent.", "Permita o microfone nos ajustes do navegador ou do sistema para usar o modo Automático. Continuando no modo Manual.": "Allow microphone access in your browser or system settings to use Automatic mode. Continuing in Manual mode.", "Nenhum microfone disponível foi encontrado. Continuando no modo Manual.": "No available microphone was found. Continuing in Manual mode.", "O microfone está ocupado ou indisponível. Confira outros aplicativos e os ajustes do sistema. Continuando no modo Manual.": "The microphone is busy or unavailable. Check other apps and your system settings. Continuing in Manual mode.", "Toque novamente em Automático para ativar o áudio neste dispositivo. Continuando no modo Manual.": "Tap Automatic again to activate audio on this device. Continuing in Manual mode.", "Abra o SePrepare pelo endereço HTTPS para usar o microfone. Continuando no modo Manual.": "Open SePrepare using its HTTPS address to use the microphone. Continuing in Manual mode.", "A detecção de fala não pôde ser iniciada. Continuando no modo Manual.": "Speech detection could not start. Continuing in Manual mode."});
Object.assign(catalogs.es,{"Pausa na fala para avançar": "Pausa al hablar para avanzar", "Pausa na fala": "Pausa al hablar", "A detecção local de fala usa o microfone apenas na sua vez. Ruídos de fundo não precisam desaparecer para avançar. Nenhum áudio é gravado ou enviado.": "La detección local del habla usa el micrófono solo en tu turno. El ruido de fondo no tiene que desaparecer para avanzar. No se graba ni se envía audio.", "Permita o microfone nos ajustes do navegador ou do sistema para usar o modo Automático. Continuando no modo Manual.": "Permite el micrófono en los ajustes del navegador o del sistema para usar el modo Automático. Continuando en modo Manual.", "Nenhum microfone disponível foi encontrado. Continuando no modo Manual.": "No se encontró un micrófono disponible. Continuando en modo Manual.", "O microfone está ocupado ou indisponível. Confira outros aplicativos e os ajustes do sistema. Continuando no modo Manual.": "El micrófono está ocupado o no está disponible. Revisa otras aplicaciones y los ajustes del sistema. Continuando en modo Manual.", "Toque novamente em Automático para ativar o áudio neste dispositivo. Continuando no modo Manual.": "Toca Automático otra vez para activar el audio en este dispositivo. Continuando en modo Manual.", "Abra o SePrepare pelo endereço HTTPS para usar o microfone. Continuando no modo Manual.": "Abre SePrepare con su dirección HTTPS para usar el micrófono. Continuando en modo Manual.", "A detecção de fala não pôde ser iniciada. Continuando no modo Manual.": "No se pudo iniciar la detección del habla. Continuando en modo Manual."});
Object.assign(catalogs.ja,{"Pausa na fala para avançar": "次のセリフに進むまでの発話の間隔", "Pausa na fala": "発話の間隔", "A detecção local de fala usa o microfone apenas na sua vez. Ruídos de fundo não precisam desaparecer para avançar. Nenhum áudio é gravado ou enviado.": "端末内の音声検出は自分の番だけマイクを使います。周囲の音が続いていても次のセリフへ進めます。音声は録音も送信もしません。", "Permita o microfone nos ajustes do navegador ou do sistema para usar o modo Automático. Continuando no modo Manual.": "自動モードを使うには、ブラウザまたはシステムの設定でマイクを許可してください。手動モードに切り替えます。", "Nenhum microfone disponível foi encontrado. Continuando no modo Manual.": "使用できるマイクが見つかりませんでした。手動モードに切り替えます。", "O microfone está ocupado ou indisponível. Confira outros aplicativos e os ajustes do sistema. Continuando no modo Manual.": "マイクが使用中か、利用できません。他のアプリやシステム設定を確認してください。手動モードに切り替えます。", "Toque novamente em Automático para ativar o áudio neste dispositivo. Continuando no modo Manual.": "もう一度「自動」をタップして、この端末の音声を有効にしてください。手動モードに切り替えます。", "Abra o SePrepare pelo endereço HTTPS para usar o microfone. Continuando no modo Manual.": "マイクを使うには、HTTPSのアドレスでSePrepareを開いてください。手動モードに切り替えます。", "A detecção de fala não pôde ser iniciada. Continuando no modo Manual.": "音声検出を開始できませんでした。手動モードに切り替えます。"});

Object.assign(catalogs.en,{"A conexão do Drive precisa ser reaberta neste navegador. Toque em Conectar novamente.": "Drive needs to reconnect in this browser. Tap Connect again."});

Object.assign(catalogs.es,{"A conexão do Drive precisa ser reaberta neste navegador. Toque em Conectar novamente.": "Es necesario volver a conectar Drive en este navegador. Toca Conectar de nuevo."});

